class Solution:
    def maxEvents(self, events: list[list[int]]) -> int:
        match_day_to_event = {}

        def can_assign(i, seen_days):
            start, end = events[i]
            for day in range(start, end + 1):
                if day in seen_days:
                    continue
                seen_days.add(day)
                if day not in match_day_to_event or can_assign(match_day_to_event[day], seen_days):
                    match_day_to_event[day] = i
                    return True
            return False

        attended = 0
        for i in range(len(events)):
            if can_assign(i, set()):
                attended += 1
        return attended

solutions.better:
class Solution:
    def maxEvents(self, events: list[list[int]]) -> int:
        used = set()
        attended = 0
        for start, end in sorted(events, key=lambda x: (x[1], x[0])):
            for day in range(start, end + 1):
                if day not in used:
                    used.add(day)
                    attended += 1
                    break
        return attended

